using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;
[InitializeOnLoad] public static class InputLivePlayChecks {
 const string Pending="InputNineLiveChecks";static List<string> rows;static int passed,index;static Step current;static Queue<Step> steps;static Keyboard keyboard;static Gamepad pad;static TrainingApprovedCharacter originalCharacter,fixture;static InputSettings old,temporary;static TrainingFighter p,o;static TrainingOverlay hud;static float start,x,startup;static int rendered;static double deadline;static string path;static int previousHistory;
 sealed class Step{public Key[] keys;public GamepadState? pad;public int frames;public bool render;public Action check,before;public string name;}
 static InputLivePlayChecks(){if(SessionState.GetBool(Pending,false))EditorApplication.update+=Tick;}
 public static void Run(){if(EditorApplication.isPlaying)throw new Exception("Use a fresh verification session");EditorSceneManager.OpenScene("Assets/Shioka/Scenes/CombatFormulaComparison.unity");SessionState.SetBool(Pending,true);EditorApplication.update-=Tick;EditorApplication.update+=Tick;EditorApplication.EnterPlaymode();}
 static void Check(bool ok,string name){rows.Add((ok?"PASS ":"FAIL ")+name);if(!ok)throw new Exception(name);passed++;}
 static void Add(string name,int n,Key[] keys,Action check=null,Action before=null,bool render=false,GamepadState? pad=null){steps.Enqueue(new Step{name=name,frames=n,keys=keys,check=check,before=before,render=render,pad=pad});}
 static readonly Key[] None=new Key[0];
 static void Setup(){rows=new List<string>();steps=new Queue<Step>();var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-liveInputReport");path=i<0?"Temp/live-input.txt":args[i+1];deadline=EditorApplication.timeSinceStartup+120;hud=UnityEngine.Object.FindAnyObjectByType<TrainingOverlay>();p=hud.player;o=p.opponent;old=InputSystem.settings;temporary=UnityEngine.Object.Instantiate(old);temporary.updateMode=InputSettings.UpdateMode.ProcessEventsManually;temporary.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;temporary.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings=temporary;keyboard=InputSystem.AddDevice<Keyboard>();pad=InputSystem.AddDevice<Gamepad>();Application.runInBackground=true;p.GetComponent<TrainingControls>().SetOptionBlocked(false);startup=p.moveSet.Find(TrainingCommand.Light).startupFrames;x=p.transform.position.x;
 Add("neutral startup",4,None);Add("live keyboard movement",6,new[]{Key.D},()=>Check(Mathf.Abs(p.transform.position.x-x)>.05f,"production source moves fighter"));Add("live jump",14,new[]{Key.W},()=>Check(p.CurrentPhase==TrainingFighter.Phase.Air,"production source starts jump"));Add("landing",70,None,()=>Check(p.IsGrounded,"ordinary landing"));
 Add("immediate LP",1,new[]{Key.J},()=>{var sample=p.InputBuffer.Samples.Last(s=>s.AttackPressedMask!=0);Check(p.InputBuffer.History.Any(h=>h.Command==TrainingCommand.Light&&h.IssuedFrame==sample.Frame),"LP queued in same sampled tick, zero confirmation wait");Check(p.CurrentPhase==TrainingFighter.Phase.Attack,"LP starts through normal buffer");Check(p.CurrentMove.startupFrames==startup&&p.V01ActionFrame<startup,"startup value preserved without compensation");Check(TrainingCommandHistory.Name(p,TrainingCommand.Light)=="LP","character history LP name");});Add("finish LP",30,None);
 Add("fixture neutral",4,None,null,()=>{hud.Session.ResetConfigured();var view=p.GetComponent<ArmoredStaticPoseView>();originalCharacter=view.characterProfile;fixture=UnityEngine.Object.Instantiate(originalCharacter);fixture.attackSlots=CharacterAttackSlot.AwariDefaults();var c=fixture.attackSlots.Single(v=>v.slot==BattleAttackSlot.C);c.assigned=true;c.command=TrainingCommand.Special;view.characterProfile=fixture;});
 var hp=new GamepadState().WithButton(GamepadButton.RightShoulder);var chord=new GamepadState().WithButton(GamepadButton.RightShoulder).WithButton(GamepadButton.LeftShoulder);chord.leftTrigger=1;
 Add("pad HP first",1,None,()=>Check(p.InputBuffer.History.Any(v=>v.Command==TrainingCommand.Heavy),"pad R1 HP immediately before modifier"),null,false,hp);
 Add("late pad chord",1,None,()=>{Check(p.InputBuffer.History.Any(v=>v.Command==TrainingCommand.Special),"late T1 queues fixture D3 through real battle buffer");Check(p.InputBuffer.Trace.Any(v=>v.Command==TrainingCommand.Heavy&&v.Outcome==TrainingCommandOutcome.Executed),"earlier HP not undone");Check(p.InputBuffer.Samples.Last().ForceHeld,"independent pad Mania alongside ABC");var history=new TrainingCommandHistory();history.Capture(p);Check(history.Text().Contains("D3"),"character D3 raw display even before execution");},null,false,chord);
 Add("held chord",2,None,()=>Check(p.InputBuffer.History.Count(v=>v.Command==TrainingCommand.Special)==1,"held D3 not repeated"),null,false,chord);
 Add("T1 release",1,None,()=>Check(p.InputBuffer.History.Count(v=>v.Command==TrainingCommand.Heavy)==1,"T1 release does not reissue HP"),null,false,hp);
 Add("T1 reforms",1,None,()=>Check(p.InputBuffer.History.Count(v=>v.Command==TrainingCommand.Special)==2,"reformed chord queues new D3"),null,false,chord);
 Add("restore fixture",2,None,null,()=>{p.GetComponent<ArmoredStaticPoseView>().characterProfile=originalCharacter;UnityEngine.Object.Destroy(fixture);fixture=null;});

 Add("reset left",4,None,null,()=>hud.Session.ResetConfigured());Add("opponent attack left",2,None,()=>Check(o.IsGuardThreatMotion,"opponent motion started"),()=>o.InputBuffer.Push(TrainingCommand.Light));Add("left FD",1,new[]{Key.A,Key.LeftShift},()=>{Check(p.FdActive,"Mania + relative back activates existing FD");foreach(int y in new[]{-1,0,1})Check(p.V01CanFD(new Vector2(-1,y)),"left 1/4/7 direction available "+y);});Add("left release",1,new[]{Key.A},()=>Check(!p.FdActive,"release Mania ends FD"));
 Add("reset right",4,None,null,()=>{hud.Session.ResetConfigured();p.GetComponent<TrainingMotor2D>().Teleport(new Vector2(.8f,.01f));o.GetComponent<TrainingMotor2D>().Teleport(new Vector2(-.8f,.01f));p.RefreshTrainingFacing();o.RefreshTrainingFacing();});Add("opponent attack right",2,None,null,()=>o.InputBuffer.Push(TrainingCommand.Light));Add("right FD",1,new[]{Key.D,Key.RightShift},()=>{Check(p.FdActive,"mirrored Mania FD");foreach(int y in new[]{-1,0,1})Check(p.V01CanFD(new Vector2(1,y)),"right 1/4/7 direction available "+y);});Add("release right",2,None);
 Add("reset before menu",4,None,null,()=>hud.Session.ResetConfigured());Add("Esc opens menu",3,new[]{Key.Escape},()=>Check(hud.OptionVisible,"Esc reaches production Options"),null,true);Add("menu neutral",3,None,null,null,true);Add("menu J",3,new[]{Key.J},()=>Check(hud.OptionVisible,"menu confirm does not close unexpectedly"),null,true);Add("held close boundary",3,new[]{Key.J},()=>Check(!p.InputBuffer.History.Any(h=>h.Command==TrainingCommand.Light),"menu confirm/held close does not leak LP"),()=>hud.SetOptionVisible(false));Add("release menu button",3,None);Add("new press after close",1,new[]{Key.J},()=>Check(p.CurrentPhase==TrainingFighter.Phase.Attack,"fresh press after neutral works"));Add("finish after menu",30,None);
 Add("reset before record",4,None,null,()=>hud.Session.ResetConfigured());Add("Record R",1,new[]{Key.R},()=>Check(hud.Session.Recorder.State==TrainingRecorder.Mode.Countdown,"R starts countdown through action frame"));Add("record countdown",182,None,()=>Check(hud.Session.Recorder.State==TrainingRecorder.Mode.Recording,"recording takes dummy control"));Add("record Mania/move",3,new[]{Key.D,Key.LeftShift});Add("stop R",1,new[]{Key.R},()=>Check(hud.Session.Recorder.State==TrainingRecorder.Mode.Idle&&hud.Session.Recorder.SavedCount>0,"R stops recording"));Add("record neutral",3,None);Add("play P",1,new[]{Key.P},()=>Check(hud.Session.Recorder.State==TrainingRecorder.Mode.Playback,"P plays saved logical input"));Add("play finish",20,None,()=>Check(hud.Session.Recorder.State==TrainingRecorder.Mode.Idle,"one-shot playback ends"));Add("Ctrl reset",1,new[]{Key.LeftCtrl},()=>Check(hud.Session.Recorder.State==TrainingRecorder.Mode.Idle,"Ctrl reset cancels transient recorder"));Add("held Ctrl no repeat",4,new[]{Key.LeftCtrl},()=>Check(p.InputBuffer.Frame>1,"held Ctrl does not reset every tick"));Add("final release",2,None);
 }
 static void Begin(){if(steps.Count==0){Finish(0);return;}current=steps.Dequeue();current.before?.Invoke();start=Time.fixedTime;rendered=0;InputSystem.QueueStateEvent(keyboard,new KeyboardState(current.keys));InputSystem.QueueStateEvent(pad,current.pad??new GamepadState());InputSystem.Update();}
 static void Tick(){try{if(!EditorApplication.isPlaying||Time.frameCount<2)return;if(keyboard==null){Setup();Begin();return;}InputSystem.Update();if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Bounded live smoke timeout at "+current?.name);rendered++;bool done=current.render?rendered>=current.frames:(Time.fixedTime-start)/Time.fixedDeltaTime>=current.frames-.01f;if(!done)return;current.check?.Invoke();rows.Add("STEP "+current.name);File.WriteAllLines(path,rows);Begin();}catch(Exception e){rows?.Add("EXCEPTION "+e);Debug.LogException(e);Finish(1);}}
 static void Finish(int exit){SessionState.SetBool(Pending,false);EditorApplication.update-=Tick;if(rows!=null){rows.Add(passed+" PASS; exit="+exit+"; actual production input with virtual Keyboard; physical devices unverified");File.WriteAllLines(path,rows);}if(keyboard!=null)InputSystem.RemoveDevice(keyboard);if(pad!=null)InputSystem.RemoveDevice(pad);if(old!=null)InputSystem.settings=old;if(temporary!=null)UnityEngine.Object.DestroyImmediate(temporary);Time.timeScale=1;EditorApplication.Exit(exit);}
}
